import type { AudioSegment } from '../../cognitiveProfile/battery';
import { playNaturalArabicAudio, stopNaturalArabicAudio, prepareArabicTtsText } from '../../utils/naturalSpeech';
import { audioKey, normalizeSpokenText } from '../../cognitiveProfile/audioCatalog';

const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));

/** Pre-recorded clips (public/audio/v1), generated by scripts/generate-audio.ts. */
const AUDIO_BASE = '/audio/v1/';
interface AudioManifest {
  version: 1;
  voice: string;
  clips: Record<string, { file: string; text?: string }>;
}
let manifestPromise: Promise<AudioManifest | null> | null = null;
let currentClip: HTMLAudioElement | null = null;
const preloadedClips = new Map<string, HTMLAudioElement>();
const MAX_PRELOADED_CLIPS = 48;
const manifestIndexCache = new WeakMap<AudioManifest, { pausal: Map<string, string>; unvowelled: Map<string, string> }>();

const stripPunctOnly = (s: string) =>
  normalizeSpokenText(s).replace(/[.،؛:!؟?]+$/g, '').trim();
const stripPausal = (s: string) =>
  normalizeSpokenText(s).replace(/[.،؛:!؟?\u064B-\u0652]+$/g, '').trim();
const stripAllVowels = (s: string) =>
  stripPausal(s).replace(/[\u064B-\u065F\u0670]/g, '');

function getSecondaryIndex(manifest: AudioManifest) {
  let idx = manifestIndexCache.get(manifest);
  if (idx) return idx;
  const pausal = new Map<string, string>();
  const unvowelled = new Map<string, string>();
  for (const entry of Object.values(manifest.clips || {})) {
    if (!entry?.file || !entry.text) continue;
    const punct = stripPunctOnly(entry.text);
    if (punct && !pausal.has(punct)) pausal.set(punct, entry.file);
    const p = stripPausal(entry.text);
    if (p && p.includes(' ') && !pausal.has(p)) pausal.set(p, entry.file);
    const u = stripAllVowels(entry.text);
    if (u && u.includes(' ') && u.length >= 14 && !unvowelled.has(u)) unvowelled.set(u, entry.file);
  }
  idx = { pausal, unvowelled };
  manifestIndexCache.set(manifest, idx);
  return idx;
}

function loadManifest(): Promise<AudioManifest | null> {
  if (!manifestPromise) {
    manifestPromise = fetch(`${AUDIO_BASE}manifest.json`, { cache: 'no-cache' })
      .then((res) => (res.ok ? (res.json() as Promise<AudioManifest>) : null))
      .catch(() => null);
  }
  return manifestPromise;
}

export function resolveClipFile(manifest: AudioManifest, text: string): string | undefined {
  if (!text) return undefined;
  const prepared = prepareArabicTtsText(text);
  const punctOnly = stripPunctOnly(text);
  const pausal = stripPausal(text);
  const unvowelled = stripAllVowels(text);

  const keysToTry = [
    audioKey(normalizeSpokenText(text)),
    text,
    text.trim(),
    audioKey(text),
    punctOnly,
    punctOnly ? audioKey(punctOnly) : undefined,
    prepared,
    prepared ? audioKey(prepared) : undefined,
    normalizeSpokenText(text),
    // Never strip vowels/harakat on isolated short words (prevents رَبُّ -> رِبْ or نَافِذَةِ -> نَافِذَةٌ).
    ...(pausal.includes(' ') ? [pausal, audioKey(pausal)] : []),
    ...(unvowelled.includes(' ') && unvowelled.length >= 14 ? [unvowelled, audioKey(unvowelled)] : []),
  ].filter(Boolean) as string[];

  for (const k of keysToTry) {
    if (manifest.clips[k]?.file) {
      return manifest.clips[k].file;
    }
  }

  const secondary = getSecondaryIndex(manifest);
  if (punctOnly && secondary.pausal.has(punctOnly)) {
    return secondary.pausal.get(punctOnly);
  }
  if (pausal.includes(' ') && secondary.pausal.has(pausal)) {
    return secondary.pausal.get(pausal);
  }
  if (unvowelled.includes(' ') && unvowelled.length >= 14 && secondary.unvowelled.has(unvowelled)) {
    return secondary.unvowelled.get(unvowelled);
  }
  return undefined;
}

function getOrCreateAudioElement(file: string): HTMLAudioElement {
  const existing = preloadedClips.get(file);
  if (existing) {
    // Refresh LRU order
    preloadedClips.delete(file);
    preloadedClips.set(file, existing);
    return existing;
  }
  const audio = new Audio(AUDIO_BASE + file);
  audio.preload = 'auto';
  if (preloadedClips.size >= MAX_PRELOADED_CLIPS) {
    const oldestKey = preloadedClips.keys().next().value;
    if (oldestKey) preloadedClips.delete(oldestKey);
  }
  preloadedClips.set(file, audio);
  return audio;
}

/** Start fetching the manifest early so the first instruction plays without delay. */
export function preloadAudioManifest(): void {
  void loadManifest();
}

/** Warm upcoming MP3 clips into browser cache + memory so playback starts instantaneously. */
export function preloadAudioClips(texts: string[]): void {
  if (typeof window === 'undefined' || texts.length === 0) return;
  void loadManifest().then((manifest) => {
    if (!manifest) return;
    for (const text of texts) {
      if (!text) continue;
      const file = resolveClipFile(manifest, text);
      if (file) {
        const audio = getOrCreateAudioElement(file);
        try {
          if (audio.readyState < 2) audio.load();
        } catch {}
      }
    }
  });
}

/** Play the recorded clip for this exact text, if one exists. Resolves false when there is none. */
async function playRecordedClip(text: string): Promise<boolean> {
  const manifest = await loadManifest();
  if (!manifest) return false;
  const file = resolveClipFile(manifest, text);
  if (!file) return false;

  return new Promise<boolean>((resolve) => {
    const audio = getOrCreateAudioElement(file);
    try {
      audio.pause();
      audio.currentTime = 0;
    } catch {}
    currentClip = audio;
    let settled = false;
    let timerId: number | undefined;
    const finish = (played: boolean) => {
      if (settled) return;
      settled = true;
      if (timerId !== undefined) window.clearTimeout(timerId);
      audio.onended = null;
      audio.onpause = null;
      audio.onerror = null;
      if (currentClip === audio) currentClip = null;
      resolve(played);
    };
    timerId = window.setTimeout(() => finish(false), 25000);
    audio.onended = () => finish(true);
    audio.onpause = () => finish(true); // stopSpeech() pauses the clip
    audio.onerror = () => finish(false);
    audio.play().catch(() => finish(false));
  });
}

/**
 * Speak one utterance and resolve when it ends. Uses the pre-recorded clip when available;
 * otherwise falls back to live synthesis, with an estimated duration when the engine never
 * reports the end (some browsers, or no Arabic voice installed).
 */
export async function speak(text: string): Promise<void> {
  const played = await playRecordedClip(text);
  if (played) return;

  // Strict Authentic Audio Policy:
  // Only authentic human voice recordings (Suhair Al Abtah) are permitted.
  // Artificial robotic / Azure synthesis fallbacks are completely eliminated.
}

export interface PlaybackHandle {
  cancelled: boolean;
}

/** Speak segments in order, calling onHighlight with each segment's highlight target. */
export async function speakSegments(
  segments: AudioSegment[],
  handle: PlaybackHandle,
  onHighlight?: (target: string | null) => void
): Promise<void> {
  for (const segment of segments) {
    if (handle.cancelled) return;
    onHighlight?.(segment.highlight ?? null);
    await speak(segment.text);
    if (handle.cancelled) return;
    if (segment.pauseAfterMs) await wait(segment.pauseAfterMs);
  }
  onHighlight?.(null);
}

export function stopSpeech(): void {
  if (currentClip) {
    currentClip.pause();
    currentClip = null;
  }
  stopNaturalArabicAudio();
}

export { wait };
